{@body const [width,setWidth]=DIL.useState(4)}
{@body const [clearId,setClearId]=DIL.useState(0)}
<box border radius="2xl" padding={3} gap={3}>
  <row align="center" justify="between">
    <title size="lg">二维自由画板</title>
    <button color="secondary" variant="outline" size="sm" onClick={()=>setClearId(v=>v+1)}><icon name="trash-2" size="xs"/> 清空画板</button>
  </row>
  <AppBlock title="Canvas 画板" variant="inline" app_block_id="drawing-canvas-v1" bind={{color,width,clearId}}>
<div id="paint-app" class="w-full">
  <div id="paint-surface" class="relative w-full overflow-hidden rounded-xl border border-black/10 bg-white dark:border-white/15" style="height:340px;touch-action:none;cursor:crosshair">
    <canvas id="paint-canvas" class="block w-full h-full" style="touch-action:none"></canvas>
    <div id="paint-hint" class="absolute inset-0 flex items-center justify-center pointer-events-none text-sm text-gray-400">按住鼠标左键，拖动即可绘画</div>
  </div>
</div>
<script>
(function(){
const canvas=document.getElementById('paint-canvas');
const surface=document.getElementById('paint-surface');
const hint=document.getElementById('paint-hint');
const ctx=canvas.getContext('2d');
let paths=[],active=null;
let color='#e5484d',width=4,lastClear=0;
function resize(){
 const r=surface.getBoundingClientRect();
 const ratio=devicePixelRatio||1;
 canvas.width=Math.round(r.width*ratio);canvas.height=Math.round(r.height*ratio);
 ctx.setTransform(ratio,0,0,ratio,0,0);draw();
}
function draw(){
 const r=surface.getBoundingClientRect();
 ctx.clearRect(0,0,r.width,r.height);
 for(const path of [...paths,...(active?[active]:[])]){
  ctx.strokeStyle=path.color;ctx.fillStyle=path.color;ctx.lineWidth=path.width;ctx.lineCap='round';ctx.lineJoin='round';
  const points=path.points;
  if(!points.length)continue;
  if(points.length===1){ctx.beginPath();ctx.arc(points[0].x*r.width,points[0].y*r.height,path.width/2,0,Math.PI*2);ctx.fill();continue;}
  ctx.beginPath();ctx.moveTo(points[0].x*r.width,points[0].y*r.height);
  for(let i=1;i<points.length;i++)ctx.lineTo(points[i].x*r.width,points[i].y*r.height);
  ctx.stroke();
 }
 hint.style.display=paths.length||active?'none':'flex';
}
function point(e){const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};}
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;canvas.setPointerCapture(e.pointerId);active={color,width,points:[point(e)]};draw();});
canvas.addEventListener('pointermove',e=>{if(!active)return;active.points.push(point(e));draw();});
function finish(){if(active){paths.push(active);active=null;draw();}}
canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);
new ResizeObserver(resize).observe(surface);
resize();
const sync=()=>{const b=globalThis.__bindings;if(!b)return;color=b.color??color;width=Number(b.width??width);if(b.clearId!==undefined&&b.clearId!==lastClear){lastClear=b.clearId;paths=[];active=null;draw();}};
globalThis.__effect?.(sync);
sync();
})();
</script>
</AppBlock>
<row align="center" justify="between" wrap="wrap">
  <row align="center" gap={2}>
    <text weight="medium" size="sm">画笔颜色</text>
    {#each [{value:"#e5484d",name:"红色"},{value:"#2563eb",name:"蓝色"}] as c}
      <button key={c.value} size="md" color={color===c.value?"primary":"secondary"} variant={color===c.value?"solid":"outline"} onClick={()=>setColor(c.value)}><icon name={color===c.value?"check-circle-2":"circle"} size="xs"/>{c.name}</button>
    {/each}
  </row>
</row>
<box gap={2}>
  <row align="center" justify="between">
    <text weight="medium" size="sm">线宽调节</text>
    <text weight="medium" tabularNums>{width} px</text>
  </row>
  <slider min={1} max={20} step={1} value={width} onChange={setWidth}/>
  <row justify="between">
    <caption>1 px · 细</caption>
    <caption>20 px · 粗</caption>
  </row>
</box>
<divider color="subtle"/>
<row align="center" gap={3} justify="between">
  <box gap={1}>
    <caption>当前画笔</caption>
    <row align="center" gap={2}>
      <box background={color} radius="full" size="14px"/>
      <text weight="medium">{color==="#e5484d"?"红色":"蓝色"} · {width} px</text>
    </row>
  </box>
  <svg viewBox="0 0 100 28" width="100px" height="28px">
    <path d="M 7 14 L 93 14" stroke={color} strokeWidth={width} strokeLinecap="round"/>
  </svg>
</row>
</box>

